```javascript
const { Client, GatewayIntentBits, Interaction, SlashCommandBuilder } = require('discord.js');

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.DirectMessages,
    GatewayIntentBits.MessageContent,
  ],
});

// Define the command builder for the "ban" command
const banCommand = new SlashCommandBuilder()
  .setName('ban')
  .setDescription('Bans a member from the server')
  .addUserOption((option) =>
    option
      .setName('user')
      .setDescription('The user to ban')
      .setRequired(true)
  )
  .addStringOption((option) =>
    option
      .setName('reason')
      .setDescription('The reason for the ban')
      .setRequired(false)
  );

// Register the "ban" command
client.on('interactionCreate', async (interaction) => {
  if (!interaction.isCommand()) return;

  const { commandName, options } = interaction;

  if (commandName === 'ban') {
    const user = options.getUser('user');
    const reason = options.getString('reason') || 'No reason provided';

    // Perform the ban action
    await interaction.guild.members.ban(user, { days: 7, reason });

    await interaction.reply({
      content: `${user.user.tag} has been banned from the server for ${reason}.`,
      ephemeral: true,
    });
  }
});

// Login the bot with the token
client.login(process.env.DISCORD_TOKEN);
```

