#include <iostream>
#include <fstream>
#include <string>
#include <map>

using namespace std;

int main() {
    string wordToCount;
    cout << "Enter the word to count: ";
    cin >> wordToCount;

    map<string, int> wordCounts;

    ifstream inputFile("input.txt");

    if (!inputFile.is_open()) {
        cerr << "Error: could not open input file" << endl;
        return 1;
    }

    string line;
    while (getline(inputFile, line)) {
        size_t pos = 0;
