            pos += wordToCount.length();
        }
    }

    inputFile.close();

    if (wordCounts[wordToCount] == 0) {
        cout << "The word \"" << wordToCount << "\" was not found in the input file" << endl;
    } else {
        cout << "The word \"" << wordToCount << "\" appears " << wordCounts[wordToCount] << " times in the input file" << endl;
    }

    return 0;
}
```

This program first prompts the user to enter the word to count, then reads the lines of the input file (`input.txt`) one by one. For each line, it searches for the word using the `find()` method of the `string` class, and increments the count in a `map` object (`wordCounts`) whenever the word is found.

